(() => {
  globalThis.__sisStudioUI.companionStyle = `
    :host{display:block;margin:18px 0 26px;color:var(--sis-text,#23262e);font:14px/1.55 var(--sis-font,system-ui);color-scheme:inherit}
    *{box-sizing:border-box} [hidden]{display:none!important} button,input,select{font:inherit;color:inherit}button,a,input,select,summary{-webkit-tap-highlight-color:transparent}button,a{touch-action:manipulation}
    button{cursor:pointer;background:var(--sis-surface,#fff);border:1px solid var(--sis-border,#dfe3e9);border-radius:7px;padding:9px 13px;line-height:1.4;font-weight:550}button:hover{background:var(--sis-primary-soft,#edf1fc)}button:disabled{cursor:wait;opacity:.65}
    button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--sis-primary,#365bbb);outline-offset:3px}
    a{color:var(--sis-primary,#365bbb);text-underline-offset:3px} h2,h3,h4,p{margin:0}h2{font-size:21px;letter-spacing:-.4px}h3{font-size:17px;margin-bottom:12px}h4{font-size:14px;margin-bottom:7px}p+p{margin-top:8px}
    .bar{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:16px 20px;background:var(--sis-surface,#fff);border:1px solid var(--sis-border,#dfe3e9);border-radius:10px}
    .bar strong{font-size:15px}.muted,small,.note{color:var(--sis-text-muted,#606674)}small{display:block;font-size:12px}.actions,.inline{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.primary{background:var(--sis-primary-soft,#edf1fc);color:var(--sis-primary,#365bbb)}
    .workspace{margin-top:12px;border:1px solid var(--sis-border,#dfe3e9);border-radius:10px;background:var(--sis-surface,#fff);overflow:clip}.heading{padding:22px 24px 15px;display:flex;gap:12px;align-items:start;justify-content:space-between}
    .tabs{display:flex;gap:3px;padding:0 20px;border-bottom:1px solid var(--sis-border,#dfe3e9);overflow-x:auto}.tabs button{border:0;border-bottom:3px solid transparent;border-radius:0;white-space:nowrap;padding:12px;color:var(--sis-text-muted,#606674);background:none}.tabs button[aria-selected=true]{color:var(--sis-primary,#365bbb);border-bottom-color:var(--sis-primary,#365bbb)}
    .tabs button:focus-visible{outline-offset:-4px;border-radius:4px 4px 0 0}.panel{padding:24px}.section+.section{margin-top:24px;padding-top:22px;border-top:1px solid var(--sis-border,#dfe3e9)}.note{font-size:13px;margin:10px 0 16px;max-width:85ch}.notice{padding:12px 15px;border:1px solid var(--sis-border,#dfe3e9);border-radius:7px;background:var(--sis-surface-secondary,#f8f9fb);margin:12px 0;font-size:13px}
    label{display:flex;flex-direction:column;gap:5px;font-size:12px;font-weight:550;min-width:0}input,select{min-height:40px;width:100%;min-width:0;background:var(--sis-surface,#fff);border:1px solid var(--sis-border,#dfe3e9);border-radius:6px;padding:8px 10px;line-height:1.3}input[type=checkbox]{width:18px;min-height:18px;accent-color:var(--sis-primary,#365bbb)}.check{flex-direction:row;align-items:center;font-size:13px}
    .fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:14px;margin:15px 0}.fields label{max-width:380px}.row{display:grid;grid-template-columns:minmax(180px,2fr) minmax(70px,.5fr) minmax(130px,1fr) 35px;gap:10px;align-items:end;padding:12px 0;border-bottom:1px solid var(--sis-border,#dfe3e9)}.row button{padding:9px 5px}.row .course{font-size:13px;font-weight:550;align-self:center}.row .course small{font-weight:400}.row input{max-width:100%}.remove{color:var(--sis-text-muted,#606674)}
    .metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:18px 0}.metric{padding:16px;background:var(--sis-surface-secondary,#f8f9fb);border:1px solid var(--sis-border,#dfe3e9);border-radius:8px;min-width:0}.metric strong{display:block;font-size:26px;line-height:1.3;font-variant-numeric:tabular-nums;margin:6px 0;overflow-wrap:anywhere}.metric span{font-size:12px;color:var(--sis-text-muted,#606674)}
    .error{color:var(--sis-danger,#b83740)}.ok{color:var(--sis-success,#16754d)}.warn{color:var(--sis-warning,#8c5e08)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:14px}.card{border:1px solid var(--sis-border,#dfe3e9);border-radius:8px;padding:17px;min-width:0}.card p{font-size:13px}.card .fields{grid-template-columns:repeat(2,minmax(0,1fr))}.card a{font-size:12px}.result{display:block;font-size:14px;margin:14px 0;font-weight:550;min-height:24px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:12px 10px;text-align:left;border-bottom:1px solid var(--sis-border,#dfe3e9);white-space:nowrap}th{font-size:12px;color:var(--sis-text-muted,#606674);font-weight:550}td:first-child{white-space:normal}details{margin-top:18px}summary{cursor:pointer;font-weight:550}ul{padding-left:20px}.room-grid{max-height:560px;overflow:auto;padding:3px}.pill{font-size:11px;display:inline-block;border:1px solid var(--sis-border,#dfe3e9);border-radius:4px;padding:2px 6px;margin:5px 0}.footer{display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap;padding:15px 24px;border-top:1px solid var(--sis-border,#dfe3e9);font-size:12px}.footer button{font-size:12px}.timeline{display:grid;gap:10px}.timeline .card{display:flex;align-items:center;justify-content:space-between;gap:16px}.timeline .current{border-color:var(--sis-primary,#365bbb)}
    dialog{color:inherit;background:var(--sis-surface,#fff);border:1px solid var(--sis-border,#dfe3e9);border-radius:12px;padding:22px;width:min(580px,calc(100vw - 32px));max-height:80dvh;box-shadow:0 20px 80px #0005}dialog::backdrop{background:#0008}.commands{display:grid;gap:6px;max-height:45dvh;overflow:auto;margin-top:14px}.commands a,.commands button{display:block;text-align:left;padding:10px 12px;text-decoration:none;border:1px solid var(--sis-border,#dfe3e9);border-radius:6px}.commands a:focus,.commands button:focus{background:var(--sis-primary-soft,#edf1fc)}
    @media(max-width:600px){.bar{padding:14px;gap:12px}.bar .actions{width:100%}.bar button{flex:1}.heading{padding:17px 15px}.panel{padding:16px}.tabs{padding:0 7px}.tabs button{padding:10px}.row{grid-template-columns:minmax(0,1fr) minmax(0,1fr) 34px}.row .course{grid-column:1/-1}.row>label:first-child{grid-column:1/-1}.fields{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.footer{padding:14px}.metric strong{font-size:24px}.timeline .card{align-items:start}.heading h2{font-size:19px}}
    @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}@media print{:host{display:none!important}}
  `;
})();
